        servers:Array.isArray(servers) ? servers.map((s,i) => ({index:i, url:s?.url ?? '', variables:Boolean(s?.variables)})) : [],
        security:Array.isArray(security) ? security.map(s => plain(s) ? Object.keys(s) : []) : [],
